import("./src/cart.js").then(m => {
  const {applyCoupon, cartTotal, shippingCents} = m;
  console.log("empty cart subtotal:", cartTotal([]), "-> shipping:", shippingCents(cartTotal([])));
  const sub = 6000;
  const disc = applyCoupon(sub, {kind:"pct", value:20});
  console.log("sub 6000, 20% off ->", disc, "| ship(pre-discount):", shippingCents(sub), "| ship(post-discount):", shippingCents(disc));
  console.log("flat coupon eats shipping if applied after:", applyCoupon(1000+599, {kind:"flat", value:1599}));
  console.log("negative:", shippingCents(-500), "NaN:", shippingCents(NaN), "undefined:", shippingCents(undefined));
  console.log("round half-up check 1005*10%:", Math.round(100.5));
});'
